    filled_col = None
    for j in type1_cols:
        if (min_r, j) in type1 and (max_r, j) in type1:
            filled_col = j
            break

    # Step 1: Fill the detected axes
    if filled_row is not None:
        # Fill entire filled row with 1s (except keep type 1s as-is)
