            shell_r = min(abs(r - filled_row) for r, c in type1)  # min distance from center to any type1 in row
            shell_c = min(abs(c - filled_col) for r, c in type1)  # min distance from center to any type1 in col

            # Active region: type 2s within a diamond with radius R
            R = shell_r + shell_c - 2  # radius based on type1 proximity

            for r in range(rows):
                for c in range(cols):
                    if grid[r][c] == 2:
